// @ts-check
import { defineConfig } from 'astro/config';
import tailwindcss from '@tailwindcss/vite';
import sitemap from '@astrojs/sitemap';
import prefixBase from './src/integrations/prefix-base.mjs';

/*
 * WHERE THE SITE LIVES
 * --------------------
 * Default: https://ehtune.github.io/  (GitHub organization "ehtune", repository "ehtune.github.io").
 *
 * To build the same site for another address (e.g. a University of Siena server),
 * you do NOT edit this file: set two environment variables instead, or run the
 * "Export site for another server" workflow on GitHub (see docs/MIGRATION.md).
 *
 *   SITE_URL   the domain only, e.g.  https://www.unisi.it
 *   BASE_PATH  the folder,     e.g.  /ehtune      (use / when the site sits at the domain root)
 */
const site = process.env.SITE_URL || 'https://ehtune.github.io';
const base = process.env.BASE_PATH || '/';

export default defineConfig({
  site,
  base,
  trailingSlash: 'ignore',
  build: { format: 'directory' },
  compressHTML: true,
  integrations: [sitemap(), prefixBase()],
  vite: { plugins: [tailwindcss()] },
});
